using System.Numerics;using System.Windows.Media;using System.Windows.Media.Media3D;
namespace DanceStudio;
// Four shared color meshes, plus constant-size guide meshes. No per-bone WPF models.
internal sealed class SkeletonVisual {
 public readonly Model3DGroup Model=new();readonly Rig rig;readonly float radius,headRadius,axisLength;readonly int head,root;
 readonly MeshGeometry3D[] meshes=new MeshGeometry3D[4];readonly int[][] members;readonly MeshGeometry3D headMesh=new(),headDirection=new();readonly MeshGeometry3D[] axes=[new(),new(),new()];
 static readonly int[] LinkTriangles=[0,1,3,1,4,3,1,2,4,2,5,4,2,0,5,0,3,5],JointTriangles=[0,2,4,2,1,4,1,3,4,3,0,4,2,0,5,1,2,5,3,1,5,0,3,5];
 public SkeletonVisual(Rig r){rig=r;head=BoneGuide.HeadIndex(r);root=BoneGuide.RootIndex(r);var world=r.World(r.Reference);float span=(world.Select(p=>p.T).Aggregate(Vector3.Max)-world.Select(p=>p.T).Aggregate(Vector3.Min)).Length();radius=Math.Clamp(span*.0025f,.15f,2f);headRadius=Math.Clamp(span*.022f,radius*2,radius*18);axisLength=Math.Max(radius*10,span*.12f);
  var groups=Enumerable.Range(0,r.Names.Length).Select(Group).ToArray();members=Enumerable.Range(0,4).Select(group=>Enumerable.Range(0,r.Names.Length).Where(i=>groups[i]==group).ToArray()).ToArray();Color[] colors=[BoneGuide.Neutral,BoneGuide.Left,BoneGuide.Right,BoneGuide.Head];for(int g=0;g<4;g++){var mesh=meshes[g]=new();Add(mesh,colors[g]);var indices=new Int32Collection();int offset=0;foreach(int i in members[g]){if(r.Parents[i]>=0){Append(indices,LinkTriangles,offset);offset+=6;}Append(indices,JointTriangles,offset);offset+=6;}mesh.TriangleIndices=indices;}
  if(head>=0){Add(headMesh,BoneGuide.Head);var triangles=new Int32Collection();for(int row=0;row<8;row++)for(int col=0;col<12;col++){int a=row*13+col;foreach(int i in new[]{a,a+1,a+13,a+1,a+14,a+13})triangles.Add(i);}headMesh.TriangleIndices=triangles;Add(headDirection,Color.FromRgb(255,207,83));headDirection.TriangleIndices=ArrowIndices();}
  Color[] axisColors=[Color.FromRgb(235,90,90),Color.FromRgb(90,220,130),Color.FromRgb(100,155,255)];for(int i=0;i<3;i++){Add(axes[i],axisColors[i]);axes[i].TriangleIndices=ArrowIndices();}Update(world);
 }
 int Group(int i)=>i==head?3:BoneGuide.Side(rig.Names[i]) switch{BoneSide.Left=>1,BoneSide.Right=>2,_=>0};
 void Add(MeshGeometry3D mesh,Color color){var m=new DiffuseMaterial(new SolidColorBrush(color));Model.Children.Add(new GeometryModel3D(mesh,m){BackMaterial=m});}
 static void Append(Int32Collection to,int[] values,int offset){foreach(int i in values)to.Add(offset+i);}
 static Point3D P(Vector3 p)=>new(p.X,p.Z,-p.Y);
 static void Tube(Point3DCollection points,Vector3 a,Vector3 b,float width){var d=b-a;var along=d.LengthSquared()>1e-10?Vector3.Normalize(d):Vector3.UnitZ;var side=Vector3.Normalize(Vector3.Cross(along,Math.Abs(along.Z)>.9?Vector3.UnitX:Vector3.UnitZ));var up=Vector3.Cross(along,side);for(int end=0;end<2;end++)for(int i=0;i<3;i++){float angle=i*(float)(Math.PI*2/3);points.Add(P((end==0?a:b)+(side*MathF.Cos(angle)+up*MathF.Sin(angle))*width));}}
 static Int32Collection ArrowIndices(){var result=new Int32Collection();Append(result,LinkTriangles,0);foreach(int i in new[]{6,7,9,7,8,9,8,6,9,6,8,7})result.Add(i);return result;}
 static void Arrow(MeshGeometry3D mesh,Vector3 start,Vector3 direction,float length,float width){var axis=Vector3.Normalize(direction);var end=start+axis*length;var points=new Point3DCollection();Tube(points,start,end-axis*length*.25f,width);var side=Vector3.Normalize(Vector3.Cross(axis,Math.Abs(axis.Z)>.9?Vector3.UnitX:Vector3.UnitZ));var up=Vector3.Cross(axis,side);for(int i=0;i<3;i++){float angle=i*(float)(Math.PI*2/3);points.Add(P(end-axis*length*.3f+(side*MathF.Cos(angle)+up*MathF.Sin(angle))*width*3));}points.Add(P(end));mesh.Positions=points;}
 public void Update(Pose[] world){for(int g=0;g<4;g++){var points=new Point3DCollection();foreach(int i in members[g]){var b=world[i].T;if(rig.Parents[i]>=0)Tube(points,world[rig.Parents[i]].T,b,radius*.6f);foreach(var offset in new[]{Vector3.UnitX,-Vector3.UnitX,Vector3.UnitY,-Vector3.UnitY,Vector3.UnitZ,-Vector3.UnitZ})points.Add(P(b+offset*radius));}meshes[g].Positions=points;}
  if(head>=0){var h=world[head];var center=h.T+Vector3.Transform(Vector3.UnitZ*headRadius*.6f,h.R);var points=new Point3DCollection();for(int row=0;row<=8;row++)for(int col=0;col<=12;col++){double latitude=Math.PI*row/8,longitude=2*Math.PI*col/12;var v=new Vector3((float)(Math.Sin(latitude)*Math.Cos(longitude)),(float)(Math.Sin(latitude)*Math.Sin(longitude)*.8),(float)(Math.Cos(latitude)*1.2));points.Add(P(center+Vector3.Transform(v*headRadius,h.R)));}headMesh.Positions=points;Arrow(headDirection,center,Vector3.Transform(Vector3.UnitY,h.R),headRadius*2.2f,radius*.7f);}
  if(root>=0){var pose=world[root];Vector3[] directions=[Vector3.UnitX,Vector3.UnitY,Vector3.UnitZ];for(int i=0;i<3;i++)Arrow(axes[i],pose.T,Vector3.Transform(directions[i],pose.R),axisLength,radius*.8f);}
 }
}
